package vn.edu.eaut.lab7.repository; import vn.edu.eaut.lab7.model.*; import java.util.*; import java.util.stream.*; public class LopHocRepository { private static final List<LopHoc> data=new ArrayList<>(List.of(new LopHoc(1,"DCCNTT15.10.1","CNTT 15.10.1","Nguyễn Văn A",35),new LopHoc(2,"DCCNTT15.10.2","CNTT 15.10.2","Trần Văn B",38))); private static int next=3; public List<LopHoc> findAll(){return data;} public LopHoc findById(int id){return data.stream().filter(x->x.getId()==id).findFirst().orElse(null);} public void add(LopHoc x){x.setId(next++);data.add(x);} public void update(LopHoc x){LopHoc o=findById(x.getId());if(o!=null){o.setMaLop(x.getMaLop());o.setTenLop(x.getTenLop());o.setCoVanHocTap(x.getCoVanHocTap());o.setSoLuongSinhVien(x.getSoLuongSinhVien());}} public void delete(int id){data.removeIf(x->x.getId()==id);} public List<LopHoc> search(String k){if(k==null||k.isBlank())return data;String q=k.toLowerCase();return data.stream().filter(x->x.getMaLop().toLowerCase().contains(q)||x.getTenLop().toLowerCase().contains(q)).collect(Collectors.toList());} }